        static IEnumerable<T> FillBackwardImpl<T>(IEnumerable<T> source, Func<T, bool> predicate, Func<T, T, T>? fillSelector)
        {
            List<T>? blanks = null;

            foreach (var item in source)
            {
                var isBlank = predicate(item);
                if (isBlank)
                {
