    /// The minimum permitted offset; 18 hours before UTC.
    /// </summary>
    static Offset IMinMaxValue<Offset>.MinValue => MinValue;

    /// <summary>
    /// The maximum permitted offset; 18 hours after UTC.
    /// </summary>
