        { 'h', (pattern, builder) => { throw new InvalidPatternException(TextErrorMessages.Hour12PatternNotSupported, typeof(Offset)); } },
        { 'H', SteppedPatternBuilder<Offset, OffsetParseBucket>.HandlePaddedField
