        newZoneProvider == ZoneProvider ? this : Create(PatternText, FormatInfo, Resolver, newZoneProvider, TemplateValue, TwoDigitYearMax);

    /// <summary>
    /// Creates a pattern like this one, but with the specified template value.
    /// </summary>
