namespace Humanizer.Localisation.Formatters
{
    internal class RussianFormatter : DefaultFormatter
    {
        public RussianFormatter()
            : base("ru")
        {
        }

        protected override string GetResourceKey(string resourceKey, int number)
        {
            var grammaticalNumber = RussianGrammaticalNumberDetector.Detect(number);
            var suffix = GetSuffix(grammaticalNumber);
            return resourceKey + suffix;
        }

        private string GetSuffix(RussianGrammaticalNumber grammaticalNumber)
        {
            if (grammaticalNumber == RussianGrammaticalNumber.Singular)
            {
                return "_Singular";
            }

            if (grammaticalNumber == RussianGrammaticalNumber.Paucal)
            {
                return "_Paucal";
            }

            return "";
        }
    }
}

namespace Humanizer.Localisation.Formatters
{
    internal class SerbianFormatter : DefaultFormatter
    {
        private const string PaucalPostfix = "_Paucal";

        public SerbianFormatter(string localeCode)
            : base(localeCode)
        {
        }

        protected override string GetResourceKey(string resourceKey, int number)
        {
            var mod10 = number % 10;

            if (mod10 > 1 && mod10 < 5)
            {
                return resourceKey + PaucalPostfix;
            }

            return resourceKey;
        }
    }
}

namespace Humanizer.Localisation.Formatters
{
    internal class SlovenianFormatter : DefaultFormatter
    {
        private const string DualPostfix = "_Dual";
        private const string TrialQuadralPostfix = "_TrialQuadral";

        public SlovenianFormatter()
            : base("sl")
        {
        }

        protected override string GetResourceKey(string resourceKey, int number)
        {
            if (number == 2)
            {
                return resourceKey + DualPostfix;
            }

            // When the count is three or four some some words have a different form when counting in Slovenian language
            if (number == 3 || number == 4)
            {
                return resourceKey + TrialQuadralPostfix;
            }

            return resourceKey;
        }
    }
}

