namespace Humanizer.Localisation.GrammaticalNumber
{
    internal enum RussianGrammaticalNumber
    {
        Singular,
        Paucal,
        Plural
    }
}

namespace Humanizer.Localisation.GrammaticalNumber
{
    internal static class RussianGrammaticalNumberDetector
    {
        public static RussianGrammaticalNumber Detect(long number)
        {
            var tens = number % 100 / 10;
            if (tens != 1)
            {
                var unity = number % 10;

                if (unity == 1) // 1, 21, 31, 41 ... 91, 101, 121 ...
                {
                    return RussianGrammaticalNumber.Singular;
                }

                if (unity > 1 && unity < 5) // 2, 3, 4, 22, 23, 24 ...
                {
                    return RussianGrammaticalNumber.Paucal;
                }
            }

            return RussianGrammaticalNumber.Plural;
        }
    }
}

using System;
using System.Collections.Generic;

namespace Humanizer.Localisation.NumberToWords
{
    internal class AfrikaansNumberToWordsConverter : GenderlessNumberToWordsConverter
    {
        private static readonly string[] UnitsMap = { "nul", "een", "twee", "drie", "vier", "vyf", "ses", "sewe", "agt", "nege", "tien", "elf", "twaalf", "dertien", "veertien", "vyftien", "sestien", "sewentien", "agtien", "negentien" };
        private static readonly string[] TensMap = { "nul", "tien", "twintig", "dertig", "veertig", "vyftig", "sestig", "sewentig", "tagtig", "negentig" };

        private static readonly Dictionary<int, string> OrdinalExceptions = new Dictionary<int, string>
        {
            {0, "nulste"},
            {1, "eerste"},
            {3, "derde"},
            {7, "sewende"},
            {8, "agste"},
            {9, "negende"},
            {10, "tiende"},
            {14, "veertiende"},
            {17, "sewentiende"},
            {19, "negentiende"}
        };

        public override string Convert(long number)
        {
            if (number > Int32.MaxValue || number < Int32.MinValue)
            {
                throw new NotImplementedException();
            }
            return Convert((int)number, false);
        }

        public override string ConvertToOrdinal(int number)
        {
            return Convert(number, true);
        }

        private string Convert(int number, bool isOrdinal)
        {
            if (number == 0)
            {
                return GetUnitValue(0, isOrdinal);
            }

            if (number < 0)
            {
                return string.Format("minus {0}", Convert(-number));
            }

            var parts = new List<string>();

            if ((number / 1000000000) > 0)
            {
                parts.Add(string.Format("{0} miljard", Convert(number / 1000000000)));
                number %= 1000000000;
            }

            if ((number / 1000000) > 0)
            {
                parts.Add(string.Format("{0} miljoen", Convert(number / 1000000)));
                number %= 1000000;
            }

            if ((number / 1000) > 0)
            {
                parts.Add(string.Format("{0} duisend", Convert(number / 1000)));
                number %= 1000;
            }

            if ((number / 100) > 0)
            {
                parts.Add(string.Format("{0} honderd", Convert(number / 100)));
                number %= 100;
            }

            if (number > 0)
            {
                //if (parts.Count != 0)
                //    parts.Add("en");

                if (number < 20)
                {
                    if (parts.Count > 0)
                    {
                        parts.Add("en");
                    }

                    parts.Add(GetUnitValue(number, isOrdinal));
                }
                else
                {
                    var lastPartValue = (number / 10) * 10;
                    var lastPart = TensMap[number / 10];
                    if ((number % 10) > 0)
                    {
                        lastPart = string.Format("{0} en {1}", GetUnitValue(number % 10, false), isOrdinal ? GetUnitValue(lastPartValue, isOrdinal) : lastPart);
                    }
                    else if ((number % 10) == 0)
                    {
                        lastPart = string.Format("{0}{1}{2}", parts.Count > 0 ? "en " : "", lastPart, isOrdinal ? "ste" : "");
                    }
                    else if (isOrdinal)
                    {
                        lastPart = lastPart.TrimEnd('~') + "ste";
                    }

                    parts.Add(lastPart);
                }
            }
            else if (isOrdinal)
            {
                parts[parts.Count - 1] += "ste";
            }

            var toWords = string.Join(" ", parts.ToArray());

            if (isOrdinal)
            {
                toWords = RemoveOnePrefix(toWords);
            }

            return toWords;
        }

        private static string GetUnitValue(int number, bool isOrdinal)
        {
            if (isOrdinal)
            {
                if (ExceptionNumbersToWords(number, out var exceptionString))
                {
                    return exceptionString;
                }
                else if (number > 19)
                {
                    return TensMap[number / 10] + "ste";
                }
                else
                {
                    return UnitsMap[number] + "de";
                }
            }
            else
            {
                return UnitsMap[number];
            }
        }

        private static string RemoveOnePrefix(string toWords)
        {
            // one hundred => hundredth
            if (toWords.StartsWith("een", StringComparison.Ordinal))
            {
                if (toWords.IndexOf("een en", StringComparison.Ordinal) != 0)
                {
                    toWords = toWords.Remove(0, 4);
                }
            }

            return toWords;
        }

        private static bool ExceptionNumbersToWords(int number, out string words)
        {
            return OrdinalExceptions.TryGetValue(number, out words);
        }
    }
}

using System.Collections.Generic;
using System.Linq;

namespace Humanizer.Localisation.NumberToWords
{
    internal class ArabicNumberToWordsConverter : GenderedNumberToWordsConverter
    {
        private static readonly string[] Groups = { "مئة", "ألف", "مليون", "مليار", "تريليون", "كوادريليون", "كوينتليون", "سكستيليون" };
        private static readonly string[] AppendedGroups = { "", "ألفاً", "مليوناً", "ملياراً", "تريليوناً", "كوادريليوناً", "كوينتليوناً", "سكستيليوناً" };
        private static readonly string[] PluralGroups = { "", "آلاف", "ملايين", "مليارات", "تريليونات", "كوادريليونات", "كوينتليونات", "سكستيليونات" };
        private static readonly string[] OnesGroup = { "", "واحد", "اثنان", "ثلاثة", "أربعة", "خمسة", "ستة", "سبعة", "ثمانية", "تسعة", "عشرة", "أحد عشر", "اثنا عشر", "ثلاثة عشر", "أربعة عشر", "خمسة عشر", "ستة عشر", "سبعة عشر", "ثمانية عشر", "تسعة عشر" };
        private static readonly string[] TensGroup = { "", "عشرة", "عشرون", "ثلاثون", "أربعون", "خمسون", "ستون", "سبعون", "ثمانون", "تسعون" };
        private static readonly string[] HundredsGroup = { "", "مئة", "مئتان", "ثلاث مئة", "أربع مئة", "خمس مئة", "ست مئة", "سبع مئة", "ثمان مئة", "تسع مئة" };
        private static readonly string[] AppendedTwos = { "مئتان", "ألفان", "مليونان", "ملياران", "تريليونان", "كوادريليونان", "كوينتليونان", "سكستيليونلن" };
        private static readonly string[] Twos = { "مئتان", "ألفان", "مليونان", "ملياران", "تريليونان", "كوادريليونان", "كوينتليونان", "سكستيليونان" };

        private static readonly string[] FeminineOnesGroup = { "", "واحدة", "اثنتان", "ثلاث", "أربع", "خمس", "ست", "سبع", "ثمان", "تسع", "عشر", "إحدى عشرة", "اثنتا عشرة", "ثلاث عشرة", "أربع عشرة", "خمس عشرة", "ست عشرة", "سبع عشرة", "ثمان عشرة", "تسع عشرة" };

        public override string Convert(long number, GrammaticalGender gender, bool addAnd = true)
        {
            if (number == 0)
            {
                return "صفر";
            }

            if (number < 0)
            {
                return string.Format("ناقص {0}", Convert(-number, gender));
            }

            var result = string.Empty;
            var groupLevel = 0;

            while (number >= 1)
            {
                var groupNumber = number % 1000;
                number /= 1000;

                var tens = groupNumber % 100;
                var hundreds = groupNumber / 100;
                var process = string.Empty;

                if (hundreds > 0)
                {
                    if (tens == 0 && hundreds == 2)
                    {
                        process = AppendedTwos[0];
                    }
                    else
                    {
                        process = HundredsGroup[hundreds];
                    }
                }

                if (tens > 0)
                {
                    if (tens < 20)
                    {
                        if (tens == 2 && hundreds == 0 && groupLevel > 0)
                        {
                            if (number == 2000 || number == 2000000 || number == 2000000000)
                            {
                                process = AppendedTwos[groupLevel];
                            }
                            else
                            {
                                process = Twos[groupLevel];
                            }
                        }
                        else
                        {
                            if (process != string.Empty)
                            {
                                process += " و ";
                            }

                            if (tens == 1 && groupLevel > 0 && hundreds == 0)
                            {
                                process += " ";
                            }
                            else
                            {
                                process += gender == GrammaticalGender.Feminine && groupLevel == 0 ? FeminineOnesGroup[tens] : OnesGroup[tens];
                            }
                        }
                    }
                    else
                    {
                        var ones = tens % 10;
                        tens = (tens / 10);

                        if (ones > 0)
                        {
                            if (process != string.Empty)
                            {
                                process += " و ";
                            }

                            process += gender == GrammaticalGender.Feminine ? FeminineOnesGroup[ones] : OnesGroup[ones];
                        }

                        if (process != string.Empty)
                        {
                            process += " و ";
                        }

                        process += TensGroup[tens];
                    }
                }

                if (process != string.Empty)
                {
                    if (groupLevel > 0)
                    {
                        if (result != string.Empty)
                        {
                            result = string.Format("{0} {1}", "و", result);
                        }

                        if (groupNumber != 2)
                        {
                            if (groupNumber % 100 != 1)
                            {
                                if (groupNumber >= 3 && groupNumber <= 10)
                                {
                                    result = string.Format("{0} {1}", PluralGroups[groupLevel], result);
                                }
                                else
                                {
                                    result = string.Format("{0} {1}", result != string.Empty ? AppendedGroups[groupLevel] : Groups[groupLevel], result);
                                }
                            }
                            else
                            {
                                result = string.Format("{0} {1}", Groups[groupLevel], result);
                            }
                        }
                    }

                    result = string.Format("{0} {1}", process, result);
                }

                groupLevel++;
            }

            return result.Trim();
        }

        private static readonly Dictionary<string, string> OrdinalExceptions = new Dictionary<string, string>
        {
            {"واحد", "الحادي"},
            {"أحد", "الحادي"},
            {"اثنان", "الثاني"},
            {"اثنا", "الثاني"},
            {"ثلاثة", "الثالث"},
            {"أربعة", "الرابع"},
            {"خمسة", "الخامس"},
            {"ستة", "السادس"},
            {"سبعة", "السابع"},
            {"ثمانية", "الثامن"},
            {"تسعة", "التاسع"},
            {"عشرة", "العاشر"},
        };

        private static readonly Dictionary<string, string> FeminineOrdinalExceptions = new Dictionary<string, string>
        {
            {"واحدة", "الحادية"},
            {"إحدى", "الحادية"},
            {"اثنتان", "الثانية"},
            {"اثنتا", "الثانية"},
            {"ثلاث", "الثالثة"},
            {"أربع", "الرابعة"},
            {"خمس", "الخامسة"},
            {"ست", "السادسة"},
            {"سبع", "السابعة"},
            {"ثمان", "الثامنة"},
            {"تسع", "التاسعة"},
            {"عشر", "العاشرة"},
        };

        public override string ConvertToOrdinal(int number, GrammaticalGender gender)
        {
            if (number == 0)
            {
                return "الصفر";
            }

            var beforeOneHundredNumber = number % 100;
            var overTensPart = number / 100 * 100;
            var beforeOneHundredWord = string.Empty;
            var overTensWord = string.Empty;

            if (beforeOneHundredNumber > 0)
            {
                beforeOneHundredWord = Convert(beforeOneHundredNumber, gender);
                beforeOneHundredWord = ParseNumber(beforeOneHundredWord, beforeOneHundredNumber, gender);
            }

            if (overTensPart > 0)
            {
                overTensWord = Convert(overTensPart);
                overTensWord = ParseNumber(overTensWord, overTensPart, gender);
            }

            var word = beforeOneHundredWord +
                (overTensPart > 0
                    ? (string.IsNullOrWhiteSpace(beforeOneHundredWord) ? string.Empty : " بعد ") + overTensWord
                    : string.Empty);
            return word.Trim();
        }

        private static string ParseNumber(string word, int number, GrammaticalGender gender)
        {
            if (number == 1)
            {
                return gender == GrammaticalGender.Feminine ? "الأولى" : "الأول";
            }

            if (number <= 10)
            {
                var ordinals = gender == GrammaticalGender.Feminine ? FeminineOrdinalExceptions : OrdinalExceptions;
                foreach (var kv in ordinals.Where(kv => word.EndsWith(kv.Key)))
                {
                    // replace word with exception
                    return word.Substring(0, word.Length - kv.Key.Length) + kv.Value;
                }
            }
            else if (number > 10 && number < 100)
            {
                var parts = word.Split(' ');
                var newParts = new string[parts.Length];
                var count = 0;

                foreach (var part in parts)
                {
                    var newPart = part;
                    var oldPart = part;

                    var ordinals = gender == GrammaticalGender.Feminine ? FeminineOrdinalExceptions : OrdinalExceptions;
                    foreach (var kv in ordinals.Where(kv => oldPart.EndsWith(kv.Key)))
                    {
                        // replace word with exception
                        newPart = oldPart.Substring(0, oldPart.Length - kv.Key.Length) + kv.Value;
                    }

                    if (number > 19 && newPart == oldPart && oldPart.Length > 1)
                    {
                        newPart = "ال" + oldPart;
                    }

                    newParts[count++] = newPart;
                }

                word = string.Join(" ", newParts);
            }
            else
            {
                word = "ال" + word;
            }

            return word;
        }
    }
}

using System;
using System.Collections.Generic;

namespace Humanizer.Localisation.NumberToWords
{
    internal class ArmenianNumberToWordsConverter : GenderlessNumberToWordsConverter
    {
        private static readonly string[] UnitsMap = { "զրո", "մեկ", "երկու", "երեք", "չորս", "հինգ", "վեց", "յոթ", "ութ", "ինը", "տաս", "տասնմեկ", "տասներկու", "տասներեք", "տասնչորս", "տասնհինգ", "տասնվեց", "տասնյոթ", "տասնութ", "տասնինը" };
        private static readonly string[] TensMap = { "զրո", "տաս", "քսան", "երեսուն", "քառասուն", "հիսուն", "վաթսուն", "յոթանասուն", "ութսուն", "իննսուն" };

        private static readonly Dictionary<long, string> OrdinalExceptions = new Dictionary<long, string>
        {
            {0, "զրոյական"},
            {1, "առաջին"},
            {2, "երկրորդ"},
            {3, "երրորդ"},
            {4, "չորրորդ"}
        };

        public override string Convert(long number)
        {
            return ConvertImpl(number, false);
        }

        public override string ConvertToOrdinal(int number)
        {
            if (ExceptionNumbersToWords(number, out var exceptionString))
            {
                return exceptionString;
            }

            return ConvertImpl(number, true);
        }

        private string ConvertImpl(long number, bool isOrdinal)
        {
            if (number == 0)
            {
                return GetUnitValue(0, isOrdinal);
            }

            if (number == long.MinValue)
            {
                return  "մինուս ինը քվինտիլիոն " +
                        "երկու հարյուր քսաներեք կվադրիլիոն " +
                        "երեք հարյուր յոթանասուներկու տրիլիոն " +
                        "երեսունվեց միլիարդ " +
                        "ութ հարյուր հիսունչորս միլիոն " +
                        "յոթ հարյուր յոթանասունհինգ հազար " +
                        "ութ հարյուր ութ";
            }

            if (number < 0)
            {
                return string.Format("մինուս {0}", ConvertImpl(-number, isOrdinal));
            }

            var parts = new List<string>();

            if ((number / 1000000000000000000) > 0)
            {
                parts.Add(string.Format("{0} քվինտիլիոն", Convert(number / 1000000000000000000)));
                number %= 1000000000000000000;
            }

            if ((number / 1000000000000000) > 0)
            {
                parts.Add(string.Format("{0} կվադրիլիոն", Convert(number / 1000000000000000)));
                number %= 1000000000000000;
            }

            if ((number / 1000000000000) > 0)

            {
                parts.Add(string.Format("{0} տրիլիոն", Convert(number / 1000000000000)));
                number %= 1000000000000;
            }

            if ((number / 1000000000) > 0)
            {
                parts.Add(string.Format("{0} միլիարդ", Convert(number / 1000000000)));
                number %= 1000000000;
            }

            if ((number / 1000000) > 0)
            {
                parts.Add(string.Format("{0} միլիոն", Convert(number / 1000000)));
                number %= 1000000;
            }

            if ((number / 1000) > 0)
            {
                if ((number / 1000) == 1)
                {
                    parts.Add("հազար");
                }
                else
                {
                    parts.Add(string.Format("{0} հազար", Convert(number / 1000)));
                }

                number %= 1000;
            }

            if ((number / 100) > 0)
            {
                if ((number / 100) == 1)
                {
                    parts.Add("հարյուր");
                }
                else
                {
                    parts.Add(string.Format("{0} հարյուր", Convert(number / 100)));
                }

                number %= 100;
            }

            if (number > 0)
            {
                if (number < 20)
                {
                    parts.Add(GetUnitValue(number, isOrdinal));
                }
                else
                {
                    var lastPart = TensMap[number / 10];
                    if ((number % 10) > 0)
                    {
                        lastPart += string.Format("{0}", GetUnitValue(number % 10, isOrdinal));
                    }
                    else if (isOrdinal)
                    {
                        lastPart += "երորդ";
                    }

                    parts.Add(lastPart);
                }
            }
            else if (isOrdinal)
            {
                parts[parts.Count - 1] += "երորդ";
            }

            var toWords = string.Join(" ", parts.ToArray());

            //if (isOrdinal)
            //{
            //    toWords = RemoveOnePrefix(toWords);
            //}

            return toWords;
        }

        private static string GetUnitValue(long number, bool isOrdinal)
        {
            if (isOrdinal)
            {
                return UnitsMap[number] + "երորդ";
            }
            else
            {
                return UnitsMap[number];
            }
        }

        private static string RemoveOnePrefix(string toWords)
        {
            // one hundred => hundredth
            if (toWords.StartsWith("մեկ", StringComparison.Ordinal))
            {
                toWords = toWords.Remove(0, 4);
            }

            return toWords;
        }

        private static bool ExceptionNumbersToWords(long number, out string words)
        {
            return OrdinalExceptions.TryGetValue(number, out words);
        }
    }
}

using System;
using System.Collections.Generic;

namespace Humanizer.Localisation.NumberToWords
{
    internal class AzerbaijaniNumberToWordsConverter : GenderlessNumberToWordsConverter
    {
        private static readonly string[] UnitsMap = { "sıfır", "bir", "iki", "üç", "dörd", "beş", "altı", "yeddi", "səkkiz", "doqquz" };
        private static readonly string[] TensMap = { "sıfır", "on", "iyirmi", "otuz", "qırx", "əlli", "altmış", "yetmiş", "səksən", "doxsan" };

        private static readonly Dictionary<char, string> OrdinalSuffix = new Dictionary<char, string>
        {
            {'ı', "ıncı"},
            {'i', "inci"},
            {'u', "uncu"},
            {'ü', "üncü"},
            {'o', "uncu"},
            {'ö', "üncü"},
            {'e', "inci"},
            {'a', "ıncı"},
            {'ə', "inci"},
        };

        public override string Convert(long input)
        {
            if (input > Int32.MaxValue || input < Int32.MinValue)
            {
                throw new NotImplementedException();
            }
            var number = (int)input;
            if (number == 0)
            {
                return UnitsMap[0];
            }

            if (number < 0)
            {
                return string.Format("mənfi {0}", Convert(-number));
            }

            var parts = new List<string>();

            if ((number / 1000000000) > 0)
            {
                parts.Add(string.Format("{0} milyard", Convert(number / 1000000000)));
                number %= 1000000000;
            }

            if ((number / 1000000) > 0)
            {
                parts.Add(string.Format("{0} milyon", Convert(number / 1000000)));
                number %= 1000000;
            }

            var thousand = (number / 1000);
            if (thousand > 0)
            {
                parts.Add(string.Format("{0} min", thousand > 1 ? Convert(thousand) : "").Trim());
                number %= 1000;
            }

            var hundred = (number / 100);
            if (hundred > 0)
            {
                parts.Add(string.Format("{0} yüz", hundred > 1 ? Convert(hundred) : "").Trim());
                number %= 100;
            }

            if ((number / 10) > 0)
            {
                parts.Add(TensMap[number / 10]);
                number %= 10;
            }

            if (number > 0)
            {
                parts.Add(UnitsMap[number]);
            }

            var toWords = string.Join(" ", parts.ToArray());

            return toWords;
        }

        public override string ConvertToOrdinal(int number)
        {
            var word = Convert(number);
            var wordSuffix = string.Empty;
            var suffixFoundOnLastVowel = false;

            for (var i = word.Length - 1; i >= 0; i--)
            {
                if (OrdinalSuffix.TryGetValue(word[i], out wordSuffix))
                {
                    suffixFoundOnLastVowel = i == word.Length - 1;
                    break;
                }
            }

            if (word[word.Length - 1] == 't')
            {
                word = word.Substring(0, word.Length - 1) + 'd';
            }

            if (suffixFoundOnLastVowel)
            {
                word = word.Substring(0, word.Length - 1);
            }

            return string.Format("{0}{1}", word, wordSuffix);
        }
    }
}

