using System;
using System.Collections.Generic;

namespace Humanizer.Localisation.NumberToWords
{
    internal class BrazilianPortugueseNumberToWordsConverter : GenderedNumberToWordsConverter
    {
        private static readonly string[] PortugueseUnitsMap = { "zero", "um", "dois", "três", "quatro", "cinco", "seis", "sete", "oito", "nove", "dez", "onze", "doze", "treze", "quatorze", "quinze", "dezesseis", "dezessete", "dezoito", "dezenove" };
        private static readonly string[] PortugueseTensMap = { "zero", "dez", "vinte", "trinta", "quarenta", "cinquenta", "sessenta", "setenta", "oitenta", "noventa" };
        private static readonly string[] PortugueseHundredsMap = { "zero", "cento", "duzentos", "trezentos", "quatrocentos", "quinhentos", "seiscentos", "setecentos", "oitocentos", "novecentos" };

        private static readonly string[] PortugueseOrdinalUnitsMap = { "zero", "primeiro", "segundo", "terceiro", "quarto", "quinto", "sexto", "sétimo", "oitavo", "nono" };
        private static readonly string[] PortugueseOrdinalTensMap = { "zero", "décimo", "vigésimo", "trigésimo", "quadragésimo", "quinquagésimo", "sexagésimo", "septuagésimo", "octogésimo", "nonagésimo" };
        private static readonly string[] PortugueseOrdinalHundredsMap = { "zero", "centésimo", "ducentésimo", "trecentésimo", "quadringentésimo", "quingentésimo", "sexcentésimo", "septingentésimo", "octingentésimo", "noningentésimo" };

        public override string Convert(long input, GrammaticalGender gender, bool addAnd = true)
        {
            if (input > 999999999999 || input < -999999999999)
            {
                throw new NotImplementedException();
            }

            var number = input;

            if (number == 0)
            {
                return "zero";
            }

            if (number < 0)
            {
                return string.Format("menos {0}", Convert(Math.Abs(number), gender));
            }

            var parts = new List<string>();

            if ((number / 1000000000) > 0)
            {
                // gender is not applied for billions
                parts.Add(number / 1000000000 >= 2
                    ? string.Format("{0} bilhões", Convert(number / 1000000000, GrammaticalGender.Masculine))
                    : string.Format("{0} bilhão", Convert(number / 1000000000, GrammaticalGender.Masculine)));

                number %= 1000000000;
            }

            if ((number / 1000000) > 0)
            {
                // gender is not applied for millions
                parts.Add(number / 1000000 >= 2
                    ? string.Format("{0} milhões", Convert(number / 1000000, GrammaticalGender.Masculine))
                    : string.Format("{0} milhão", Convert(number / 1000000, GrammaticalGender.Masculine)));

                number %= 1000000;
            }

            if ((number / 1000) > 0)
            {
                // gender is not applied for thousands
                parts.Add(number / 1000 == 1 ? "mil" : string.Format("{0} mil", Convert(number / 1000, GrammaticalGender.Masculine)));
                number %= 1000;
            }

            if ((number / 100) > 0)
            {
                if (number == 100)
                {
                    parts.Add(parts.Count > 0 ? "e cem" : "cem");
                }
                else
                {
                    // Gender is applied to hundreds starting from 200
                    parts.Add(ApplyGender(PortugueseHundredsMap[(number / 100)], gender));
                }

                number %= 100;
            }

            if (number > 0)
            {
                if (parts.Count != 0)
                {
                    parts.Add("e");
                }

                if (number < 20)
                {
                    parts.Add(ApplyGender(PortugueseUnitsMap[number], gender));
                }
                else
                {
                    var lastPart = PortugueseTensMap[number / 10];
                    if ((number % 10) > 0)
                    {
                        lastPart += string.Format(" e {0}", ApplyGender(PortugueseUnitsMap[number % 10], gender));
                    }

                    parts.Add(lastPart);
                }
            }

            return string.Join(" ", parts.ToArray());
        }

        public override string ConvertToOrdinal(int number, GrammaticalGender gender)
        {
            // N/A in Portuguese ordinal
            if (number == 0)
            {
                return "zero";
            }

            var parts = new List<string>();

            if ((number / 1000000000) > 0)
            {
                parts.Add(number / 1000000000 == 1
                    ? ApplyOrdinalGender("bilionésimo", gender)
                    : string.Format("{0} " + ApplyOrdinalGender("bilionésimo", gender), ConvertToOrdinal(number / 1000000000, gender)));

                number %= 1000000000;
            }

            if ((number / 1000000) > 0)
            {
                parts.Add(number / 1000000 == 1
                    ? ApplyOrdinalGender("milionésimo", gender)
                    : string.Format("{0}" + ApplyOrdinalGender("milionésimo", gender), ConvertToOrdinal(number / 1000000000, gender)));

                number %= 1000000;
            }

            if ((number / 1000) > 0)
            {
                parts.Add(number / 1000 == 1
                    ? ApplyOrdinalGender("milésimo", gender)
                    : string.Format("{0} " + ApplyOrdinalGender("milésimo", gender), ConvertToOrdinal(number / 1000, gender)));

                number %= 1000;
            }

            if ((number / 100) > 0)
            {
                parts.Add(ApplyOrdinalGender(PortugueseOrdinalHundredsMap[number / 100], gender));
                number %= 100;
            }

            if ((number / 10) > 0)
            {
                parts.Add(ApplyOrdinalGender(PortugueseOrdinalTensMap[number / 10], gender));
                number %= 10;
            }

            if (number > 0)
            {
                parts.Add(ApplyOrdinalGender(PortugueseOrdinalUnitsMap[number], gender));
            }

            return string.Join(" ", parts.ToArray());
        }

        private static string ApplyGender(string toWords, GrammaticalGender gender)
        {
            if (gender != GrammaticalGender.Feminine)
            {
                return toWords;
            }

            if (toWords.EndsWith("os"))
            {
                return toWords.Substring(0, toWords.Length - 2) + "as";
            }

            if (toWords.EndsWith("um"))
            {
                return toWords.Substring(0, toWords.Length - 2) + "uma";
            }

            if (toWords.EndsWith("dois"))
            {
                return toWords.Substring(0, toWords.Length - 4) + "duas";
            }

            return toWords;
        }

        private static string ApplyOrdinalGender(string toWords, GrammaticalGender gender)
        {
            if (gender == GrammaticalGender.Feminine)
            {
                return toWords.TrimEnd('o') + 'a';
            }

            return toWords;
        }
    }
}

using System;
using System.Collections.Generic;

namespace Humanizer.Localisation.NumberToWords
{
    internal class BulgarianNumberToWordsConverter : GenderedNumberToWordsConverter
    {
        private static readonly string[] UnitsMap =
        {
            "нула", "един", "две", "три", "четири", "пет", "шест", "седем", "осем", "девет", "десет", "единадесет",
            "дванадесет", "тринадесет", "четиринадесет", "петнадесет", "шестнадесет", "седемнадесет", "осемнадесет",
            "деветнадесет"
        };

        private static readonly string[] TensMap =
        {
            "нула", "десет", "двадесет", "тридесет", "четиридесет", "петдесет", "шестдесет", "седемдесет",
            "осемдесет", "деветдесет"
        };

        private static readonly string[] HundredsMap =
        {
            "нула", "сто", "двеста", "триста", "четиристотин", "петстотин", "шестстотин", "седемстотин",
            "осемстотин", "деветстотин"
        };


        private static readonly string[] HundredsOrdinalMap =
        {
            String.Empty, "стот", "двест", "трист", "четиристот", "петстот", "шестстот", "седемстот", "осемстот",
            "деветстот"
        };


        private static readonly string[] UnitsOrdinal =
        {
            string.Empty, "първ", "втор", "трет", "четвърт", "пет", "шест", "седм", "осм", "девeт", "десeт",
            "единадесет", "дванадесет", "тринадесет", "четиринадесет", "петнадесет", "шестнадесет", "седемнадесет",
            "осемнадесет", "деветнадесет"
        };

        public override string Convert(long input, GrammaticalGender gender, bool addAnd = true)
        {
            return Convert(input, gender, false);
        }

        private string Convert(long input, GrammaticalGender gender, bool isOrdinal, bool addAnd = true)
        {
            if (input > int.MaxValue || input < int.MinValue)
            {
                throw new NotImplementedException();
            }

            if (input == 0)
            {
                return isOrdinal ? "нулев" + GetEndingForGender(gender, input) : "нула";
            }


            var parts = new List<string>();

            if (input < 0)
            {
                parts.Add("минус");
                input = -input;
            }

            string lastOrdinalSubstitution = "";

            if ((input / 1000000000000) > 0)
            {
                if (isOrdinal)
                    lastOrdinalSubstitution = Convert(input / 1000000000000, gender, false) + " трилион" +
                                              GetEndingForGender(gender, input);
                input %= 1000000000000;
            }

            if ((input / 1000000000) > 0)
            {
                parts.Add(Convert(input / 1000000000, gender, false) +
                          $" {(input < 2000000000 ? "милиард" : "милиарда")}");

                if (isOrdinal)
                    lastOrdinalSubstitution = Convert(input / 1000000000, gender, false) + " милиард" +
                                              GetEndingForGender(gender, input);
                input %= 1000000000;
            }

            if ((input / 1000000) > 0)
            {
                parts.Add(Convert(input / 1000000, gender, false) + $" {(input < 2000000 ? "милион" : "милиона")}");

                if (isOrdinal)
                    lastOrdinalSubstitution = Convert(input / 1000000, gender, false) + " милион" +
                                              GetEndingForGender(gender, input);

                input %= 1000000;
            }

            if ((input / 1000) > 0)
            {
                if (input < 2000)
                    parts.Add("хиляда");
                else
                {
                    parts.Add(Convert(input / 1000, gender, false) + " хиляди");
                }

                if (isOrdinal)
                    lastOrdinalSubstitution = Convert(input / 1000, gender, false) + " хиляд" +
                                              GetEndingForGender(gender, input);

                input %= 1000;
            }

            if (input / 100 > 0)
            {
                parts.Add(HundredsMap[(int)input / 100]);

                if (isOrdinal)
                    lastOrdinalSubstitution = HundredsOrdinalMap[(int)input / 100] + GetEndingForGender(gender, input);

                input %= 100;
            }


            if (input > 19)
            {
                parts.Add(TensMap[input / 10]);

                if (isOrdinal)
                    lastOrdinalSubstitution = TensMap[(int)input / 10] + GetEndingForGender(gender, input);

                input %= 10;
            }

            if (input > 0)
            {
                parts.Add(UnitsMap[input]);

                if (isOrdinal)
                    lastOrdinalSubstitution = UnitsOrdinal[input] + GetEndingForGender(gender, input);
            }

            if (parts.Count > 1)
            {
                parts.Insert(parts.Count - 1, "и");
            }


            if (isOrdinal && !string.IsNullOrWhiteSpace(lastOrdinalSubstitution))
                parts[parts.Count - 1] = lastOrdinalSubstitution;

            return string.Join(" ", parts);
        }

        public override string ConvertToOrdinal(int input, GrammaticalGender gender)
        {
            return Convert(input, gender, true);
        }

        private static string GetEndingForGender(GrammaticalGender gender, long input)
        {
            if (input == 0)
            {
                return gender switch
                {
                    GrammaticalGender.Masculine => "",
                    GrammaticalGender.Feminine => "а",
                    GrammaticalGender.Neuter => "о",
                    _ => throw new ArgumentOutOfRangeException(nameof(gender))
                };
            }

            if (input < 99)
            {
                return gender switch
                {
                    GrammaticalGender.Masculine => "и",
                    GrammaticalGender.Feminine => "а",
                    GrammaticalGender.Neuter => "о",
                    _ => throw new ArgumentOutOfRangeException(nameof(gender))
                };
            }
            else
            {
                return gender switch
                {
                    GrammaticalGender.Masculine => "ен",
                    GrammaticalGender.Feminine => "на",
                    GrammaticalGender.Neuter => "но",
                    _ => throw new ArgumentOutOfRangeException(nameof(gender))
                };
            }
        }
    }
}

using System;
