namespace Humanizer.Localisation.NumberToWords
{
    internal class CentralKurdishNumberToWordsConverter : GenderlessNumberToWordsConverter
    {
        private static readonly string[] KurdishHundredsMap = { "سفر", "سەد", "دوو سەد", "سێ سەد", "چوار سەد", "پێنج سەد", "شەش سەد", "حەوت سەد", "هەشت سەد", "نۆ سەد" };
        private static readonly string[] KurdishTensMap = { "سفر", "دە", "بیست", "سی", "چل", "پەنجا", "شەست", "حەفتا", "هەشتا", "نەوەد" };
        private static readonly string[] KurdishUnitsMap = { "سفر", "یەک", "دوو", "سێ", "چوار", "پێنج", "شەش", "حەوت", "هەشت", "نۆ", "دە", "یازدە", "دوازدە", "سێزدە", "چواردە", "پازدە", "شازدە", "حەڤدە", "هەژدە", "نۆزدە" };

        public override string Convert(long number)
        {
            var largestNumber = (Math.Pow(10, 15) * 1000) - 1;
            if (number > largestNumber || number < -largestNumber)
            {
                throw new NotImplementedException();
            }

            if (number < 0)
            {
                return string.Format("نێگەتیڤ {0}", Convert(-number));
            }

            if (number == 0)
            {
                return "سفر";
            }

            var kurdishGroupsMap = new Dictionary<long, Func<long, string>>
            {
                {(long)Math.Pow(10, 15), n => string.Format("{0} کوادریلیۆن", Convert(n)) },
                {(long)Math.Pow(10, 12), n => string.Format("{0} تریلیۆن", Convert(n)) },
                {(long)Math.Pow(10, 9), n => string.Format("{0} میلیارد", Convert(n)) },
                {(long)Math.Pow(10, 6), n => string.Format("{0} میلیۆن", Convert(n)) },
                {(long)Math.Pow(10, 3), n => string.Format("{0} هەزار", Convert(n)) },
                {(long)Math.Pow(10, 2), n => KurdishHundredsMap[n]}
            };

            var parts = new List<string>();
            foreach (var group in kurdishGroupsMap.Keys)
            {
                if (number / group > 0)
                {
                    parts.Add(kurdishGroupsMap[group](number / group));
                    number %= group;
                }
            }

            if (number >= 20)
            {
                parts.Add(KurdishTensMap[number / 10]);
                number %= 10;
            }

            if (number > 0)
            {
                parts.Add(KurdishUnitsMap[number]);
            }

            var sentence = string.Join(" و ", parts);
            if (sentence.StartsWith("یەک هەزار"))
                return sentence.Substring(" یەک".Length);
            else
                return sentence;
        }

        public override string ConvertToOrdinal(int number)
        {
            var word = Convert(number);
            return string.Format("{0}{1}", word, IsVowel(word[word.Length - 1]) ? "یەم" : "ەم");
        }

        private bool IsVowel(char c)
        {
            return c == 'ا' ||
                c == 'ێ' ||
                c == 'ۆ' ||
                c == 'ە' ||
                c == 'ی';
        }
    }
}

using System.Collections.Generic;

namespace Humanizer.Localisation.NumberToWords
{
    internal class ChineseNumberToWordsConverter : GenderlessNumberToWordsConverter
    {
        private static readonly string[] UnitsMap = { "零", "一", "二", "三", "四", "五", "六", "七", "八", "九", "十" };

        public override string Convert(long number)
        {
            return Convert(number, false, IsSpecial(number));
        }

        public override string ConvertToOrdinal(int number)
        {
            return Convert(number, true, IsSpecial(number));
        }

        private bool IsSpecial(long number) => number > 10 && number < 20;

        private string Convert(long number, bool isOrdinal, bool isSpecial)
        {
            if (number == 0)
            {
                return UnitsMap[0];
            }

            if (number < 0)
            {
                return string.Format("负 {0}", Convert(-number, false, false));
            }

            var parts = new List<string>();

            if ((number / 1000000000000) > 0)
            {
                var format = "{0}兆";
                if (number % 1000000000000 < 100000000000 && number % 1000000000000 > 0)
                {
                    format = "{0}兆零";
                }

                parts.Add(string.Format(format, Convert(number / 1000000000000, false, false)));
                number %= 1000000000000;
            }

            if ((number / 100000000) > 0)
            {
                var format = "{0}亿";
                if (number % 100000000 < 10000000 && number % 100000000 > 0)
                {
                    format = "{0}亿零";
                }

                parts.Add(string.Format(format, Convert(number / 100000000, false, false)));
                number %= 100000000;
            }

            if ((number / 10000) > 0)
            {
                var format = "{0}万";
                if (number % 10000 < 1000 && number % 10000 > 0)
                {
                    format = "{0}万零";
                }

                parts.Add(string.Format(format, Convert(number / 10000, false, false)));
                number %= 10000;
            }

            if ((number / 1000) > 0)
            {
                var format = "{0}千";
                if (number % 1000 < 100 && number % 1000 > 0)
                {
                    format = "{0}千零";
                }

                parts.Add(string.Format(format, Convert(number / 1000, false, false)));
                number %= 1000;
            }

            if ((number / 100) > 0)
            {
                var format = "{0}百";
                if (number % 100 < 10 && number % 100 > 0)
                {
                    format = "{0}百零";
                }

                parts.Add(string.Format(format, Convert(number / 100, false, false)));
                number %= 100;
            }

            if (number > 0)
            {
                if (number <= 10)
                {
                    parts.Add(UnitsMap[number]);
                }
                else
                {
                    var lastPart = string.Format("{0}十", UnitsMap[number / 10]);
                    if ((number % 10) > 0)
                    {
                        lastPart += string.Format("{0}", UnitsMap[number % 10]);
                    }

                    parts.Add(lastPart);
                }
            }

            var toWords = string.Join("", parts.ToArray());

            if (isSpecial)
            {
                toWords = toWords.Substring(1);
            }

            if (isOrdinal)
            {
                toWords = string.Format("第 {0}", toWords);
            }

            return toWords;
        }
    }
}

using System;
