namespace Humanizer.Localisation.NumberToWords
{
    internal class KoreanNumberToWordsConverter : GenderlessNumberToWordsConverter
    {
        private static readonly string[] UnitsMap1 = { "", "", "이", "삼", "사", "오", "육", "칠", "팔", "구" };
        private static readonly string[] UnitsMap2 = { "", "십", "백", "천" };
        private static readonly string[] UnitsMap3 = { "", "만", "억", "조", "경", "해", "자", "양", "구", "간", "정", "재", "극", "항하사", "아승기", "나유타", "불가사의", "무량대수"};

        private static readonly Dictionary<long, string> OrdinalExceptions = new Dictionary<long, string>
        {
            {0, "영번째"},
            {1, "첫번째"},
            {2, "두번째"},
            {3, "세번째"},
            {4, "네번째"},
            {5, "다섯번째"},
            {6, "여섯번째"},
            {7, "일곱번째"},
            {8, "여덟번째"},
            {9, "아홉번째"},
            {10, "열번째"},
            {11, "열한번째"},
            {12, "열두번째"},
            {13, "열세번째"},
            {14, "열네번째"},
            {15, "열다섯번째"},
            {16, "열여섯번째"},
            {17, "열일곱번째"},
            {18, "열여덟번째"},
            {19, "열아홉째"},
        };

        public override string Convert(long number)
        {
            return ConvertImpl(number, false);
        }

        public override string ConvertToOrdinal(int number)
        {
            return ConvertImpl(number, true);
        }

        private string ConvertImpl(long number, bool isOrdinal)
        {
            if (isOrdinal && number < 20)
            {
                if (OrdinalExceptions.TryGetValue(number, out var words))
                    return words;
            }

            if (number == 0)
            {
                return "영";
            }

            if (number < 0)
            {
                return string.Format("마이너스 {0}", ConvertImpl(-number, false));
            }

            var parts = new List<string>();
            var groupLevel = 0;
            while (number > 0)
            {
                var groupNumber = number % 10000;
                number /= 10000;

                var n0 = groupNumber % 10;
                var n1 = (groupNumber % 100 - groupNumber % 10) / 10;
                var n2 = (groupNumber % 1000 - groupNumber % 100) / 100;
                var n3 = (groupNumber - groupNumber % 1000) / 1000;

                parts.Add(
                    UnitsMap1[n3] + (n3 == 0 ? "" : UnitsMap2[3])
                    + UnitsMap1[n2] + (n2 == 0 ? "" : UnitsMap2[2])
                    + UnitsMap1[n1] + (n1 == 0 ? "" : UnitsMap2[1])
                    + (n0 == 1 ? "일" : UnitsMap1[n0])
                    + (groupNumber == 0 ? "" : UnitsMap3[groupLevel])
                );

                groupLevel++;
            }

            parts.Reverse();
            var toWords = string.Join("", parts.ToArray());

            if (isOrdinal)
            {
                toWords = string.Format("{0}번째", toWords);
            }

            return toWords;
        }
    }
}

using System;
using System.Collections.Generic;

namespace Humanizer.Localisation.NumberToWords
{
    internal class LatvianNumberToWordsConverter : GenderedNumberToWordsConverter
    {
        private static readonly string[] UnitsMap = { "nulle", "vien", "div", "trīs", "četr", "piec", "seš", "septiņ", "astoņ", "deviņ", "desmit", "vienpadsmit", "divpadsmit", "trīspadsmit", "četrpadsmit", "piecpadsmit", "sešpadsmit", "septiņpadsmit", "astoņpadsmit", "deviņpadsmit" };
        private static readonly string[] TensMap = { "nulle", "desmit", "divdesmit", "trīsdesmit", "četrdesmit", "piecdesmit", "sešdesmit", "septiņdesmit", "astoņdesmit", "deviņdesmit" };
        private static readonly string[] HundredsMap = { "nulle", "simt", "divsimt", "trīssimt", "četrsimt", "piecsimt", "sešsimt", "septiņsimt", "astoņsimt", "deviņsimt" };
        private static readonly string[] UnitsOrdinal = { string.Empty, "pirm", "otr", "treš", "ceturt", "piekt", "sest", "septīt", "astot", "devīt", "desmit", "vienpadsmit", "divpadsmit", "trīspadsmit", "četrpadsmit", "piecpadsmit", "sešpadsmit", "septiņpadsmit", "astoņpadsmit", "deviņpadsmit", "divdesmit" };

        public override string Convert(long input, GrammaticalGender gender, bool addAnd = true)
        {
            if (input > int.MaxValue || input < int.MinValue)
            {
                throw new NotImplementedException();
            }

            var parts = new List<string>();
            var number = (long)input;

            if ((number / 1000000) > 0)
            {
                var millionPart = "";
                if (number == 1000000)
                {
                    millionPart = "miljons";
                }
                else
                {
                    millionPart = Convert(number / 1000000, GrammaticalGender.Masculine) + " miljoni";
                }
                number %= 1000000;
                parts.Add(millionPart);
            }

            if ((number / 1000) > 0)
            {
                var thousandsPart = "";
                if (number == 1000)
                {
                    thousandsPart = "tūkstotis";
                }
                else if (number > 1000 && number < 2000)
                {
                    thousandsPart = "tūkstoš";
                }
                else
                {
                    thousandsPart = Convert(number / 1000, GrammaticalGender.Masculine) + " tūkstoši";
                }
                parts.Add(thousandsPart);
                number %= 1000;
            }

            if ((number / 100) > 0)
            {
                var hundredsPart = "";
                if (number == 100)
                {
                    hundredsPart = parts.Contains("tūkstoš") ? "viens simts" : "simts";
                }
                else if (number > 100 && number < 200)
                {
                    hundredsPart = "simtu";
                }
                else
                {
                    hundredsPart = Convert(number / 100, GrammaticalGender.Masculine) + " simti";
                }
                parts.Add(hundredsPart);
                number %= 100;
            }

            if (number > 19)
            {
                var tensPart = TensMap[(number / 10)];
                parts.Add(tensPart);
                number %= 10;
            }

            if (number > 0)
            {
                parts.Add(UnitsMap[number] + GetCardinalEndingForGender(gender, number));
            }

            return string.Join(" ", parts);
        }

        public override string ConvertToOrdinal(int input, GrammaticalGender gender)
        {
            if (input == 0)
            {
                return "nulle";
            }

            var parts = new List<string>();

            if (input < 0)
            {
                parts.Add("mīnus");
                input = -input;
            }

            var number = (long)input;

            if ((number / 1000000) > 0)
            {
                var millionPart = "";
                if (number == 1000000)
                {
                    millionPart = "miljon" + GetOrdinalEndingForGender(gender);
                }
                else
                {
                    millionPart = Convert(number / 1000000, GrammaticalGender.Masculine) + " miljon" + GetOrdinalEndingForGender(gender);
                }
                number %= 1000000;
                parts.Add(millionPart);
            }

            if ((number / 1000) > 0)
            {
                var thousandsPart = "";
                if ((number % 1000) == 0)
                {
                    if (number == 1000)
                    {
                        thousandsPart = "tūkstoš" + GetOrdinalEndingForGender(gender);
                    }
                    else
                    {
                        thousandsPart = Convert(number / 1000, GrammaticalGender.Masculine) + " tūkstoš" + GetOrdinalEndingForGender(gender);
                    }
                }
                else
                {
                    if (number > 1000 && number < 2000)
                    {
                        thousandsPart = "tūkstoš";
                    }
                    else
                    {
                        thousandsPart = Convert(number / 1000, GrammaticalGender.Masculine) + " tūkstoši";
                    }
                }
                parts.Add(thousandsPart);
                number %= 1000;
            }

            if ((number / 100) > 0)
            {
                var hundredsPart = "";
                if ((number % 100) == 0)
                {
                    hundredsPart = HundredsMap[(number / 100)] + GetOrdinalEndingForGender(gender);
                }
                else
                {
                    if (number > 100 && number < 200)
                    {
                        hundredsPart = "simtu";
                    }
                    else
                    {
                        hundredsPart = Convert(number / 100, GrammaticalGender.Masculine) + " simti";
                    }
                }
                parts.Add(hundredsPart);
                number %= 100;
            }

            if (number > 19)
            {
                var tensPart = TensMap[(number / 10)];
                if ((number % 10) == 0)
                {
                    tensPart += GetOrdinalEndingForGender(gender);
                }
                parts.Add(tensPart);
                number %= 10;
            }

            if (number > 0)
            {
                parts.Add(UnitsOrdinal[number] + GetOrdinalEndingForGender(gender));
            }

            return string.Join(" ", parts);
        }

        private static string GetOrdinalEndingForGender(GrammaticalGender gender)
        {
            switch (gender)
            {
                case GrammaticalGender.Masculine:
                    {
                        return "ais";
                    }
                case GrammaticalGender.Feminine:
                    {
                        return "ā";
                    }
                default:
                    throw new ArgumentOutOfRangeException(nameof(gender));
            }
        }

        private static string GetCardinalEndingForGender(GrammaticalGender gender, long number)
        {
            switch (gender)
            {
                case GrammaticalGender.Masculine:
                    if (number == 1)
                    {
                        return "s";
                    }

                    if (number != 3 && number < 10)
                    {
                        return "i";
                    }

                    return "";
                case GrammaticalGender.Feminine:
                    if (number == 1)
                    {
                        return "a";
                    }

                    if (number != 3 && number < 10)
                    {
                        return "as";
                    }

                    return "";
                default:
                    throw new ArgumentOutOfRangeException(nameof(gender));
            }
        }
    }
}

using System;
using System.Collections.Generic;

namespace Humanizer.Localisation.NumberToWords
{
    internal class MalteseNumberToWordsConvertor : GenderedNumberToWordsConverter
    {
        private static readonly string[] OrdinalOverrideMap =
        {
            "0", "l-ewwel", "it-tieni", "it-tielet", "ir-raba'", "il-ħames", "is-sitt", "is-seba'", "it-tmien", "id-disa'",
            "l-għaxar", "il-ħdax", "it-tnax", "it-tlettax", "l-erbatax", "il-ħmistax", "is-sittax", "is-sbatax",
            "it-tmintax", "id-dsatax", "l-għoxrin"
        };

        private static readonly string[] UnitsMap =
        {
            "żero", "wieħed", "tnejn", "tlieta", "erbgħa", "ħamsa", "sitta", "sebgħa", "tmienja", "disgħa", "għaxra",
            "ħdax", "tnax", "tlettax", "erbatax", "ħmistax", "sittax", "sbatax", "tmintax", "dsatax"
        };

        private static readonly string[] TensMap =
            {"zero", "għaxra", "għoxrin", "tletin", "erbgħin", "ħamsin", "sittin", "sebgħin", "tmenin", "disgħin"};

        private static readonly string[] HundredsMap =
        {
            string.Empty, string.Empty, string.Empty, "tlett", "erbgħa", "ħames", "sitt", "sebgħa", "tminn", "disgħa",
            "għaxar"
        };

        private static readonly string[] PrefixMap =
        {
            string.Empty, string.Empty, string.Empty, "tlett", "erbat", "ħamest", "sitt", "sebat", "tmint", "disat",
            "għaxart", "ħdax-il", "tnax-il", "tletax-il", "erbatax-il", "ħmistax-il", "sittax-il", "sbatax-il",
            "tmintax-il", "dsatax-il"
        };

        public override string Convert(long input, GrammaticalGender gender, bool addAnd = true)
        {
            bool negativeNumber = false;

            if (input < 0)
            {
                negativeNumber = true;
                input = input * -1;
            }

            if (input < 1000000000)
            {
                return GetMillions(input, gender) + (negativeNumber ? " inqas minn żero" : String.Empty);
            }

            var billions = input / 1000000000;
            var tensInBillions = billions % 100;
            var millions = input % 1000000000;

            var billionsText = GetPrefixText(billions, tensInBillions, "biljun", "żewġ biljuni", "biljuni", false, gender);
            var millionsText = GetMillions(millions, gender);

            if (millions == 0)
            {
                return billionsText;
            }

            return $"{billionsText} u {millionsText}" + (negativeNumber ? " inqas minn żero" : String.Empty);
        }

        public override string ConvertToOrdinal(int number, GrammaticalGender gender)
        {
            if (number <= 20)
            {
                return OrdinalOverrideMap[number];
            }

            var ordinal = Convert(number, gender);

            if (ordinal.StartsWith("d"))
            {
                return $"id-{Convert(number, gender)}";
            }
            if (ordinal.StartsWith("s"))
            {
                return $"is-{Convert(number, gender)}";
            }
            if (ordinal.StartsWith("t"))
            {
                return $"it-{Convert(number, gender)}";
            }
            if (ordinal.StartsWith("e"))
            {
                return $"l-{Convert(number, gender)}";
            }
            return $"il-{Convert(number, gender)}";
        }

        private static string GetTens(long value, bool usePrefixMap, bool usePrefixMapForLowerDigits, GrammaticalGender gender)
        {
            if (value == 1 && gender == GrammaticalGender.Feminine)
            {
                return "waħda";
            }

            if (value < 11 && usePrefixMap && usePrefixMapForLowerDigits)
            {
                return PrefixMap[value];
            }

            if (value < 11 && usePrefixMap && !usePrefixMapForLowerDigits)
            {
                return HundredsMap[value];
            }

            if (value > 10 && value < 20 && usePrefixMap)
            {
                return PrefixMap[value];
            }

            if (value < 20)
            {
                return UnitsMap[value];
            }

            var single = value % 10;
            var numberOfTens = value / 10;
            if (single == 0)
            {

                return TensMap[numberOfTens];
            }

            return $"{UnitsMap[single]} u {TensMap[numberOfTens]}";
        }

        private static string GetHundreds(long value, bool usePrefixMap, bool usePrefixMapForLowerValueDigits, GrammaticalGender gender)
        {
            if (value < 100)
            {
                return GetTens(value, usePrefixMap, usePrefixMapForLowerValueDigits, gender);
            }

            var tens = value % 100;
            var numberOfHundreds = value / 100;

            var hundredsText = string.Empty;
            if (numberOfHundreds == 1)
            {
                hundredsText = "mija";
            }
            else if (numberOfHundreds == 2)
            {
                hundredsText = "mitejn";
            }
            else
            {
                hundredsText = HundredsMap[numberOfHundreds] + " mija";
            }

            if (tens == 0)
            {
                return hundredsText;
            }

            return $"{hundredsText} u {GetTens(tens, usePrefixMap, usePrefixMapForLowerValueDigits, gender)}";
        }

        private static string GetThousands(long value, GrammaticalGender gender)
        {
            if (value < 1000)
            {
                return GetHundreds(value, false, false, gender);
            }

            var thousands = value / 1000;
            var tensInThousands = thousands % 100;
            var hundreds = value % 1000;

            var thousandsInText = GetPrefixText(thousands, tensInThousands, "elf", "elfejn", "elef", true, gender);

            var hundredsInText = GetHundreds(hundreds, false, false, gender);

            if (hundreds == 0)
            {
                return thousandsInText;
            }

            return $"{thousandsInText} u {hundredsInText}";
        }

        private static string GetMillions(long value, GrammaticalGender gender)
        {
            if (value < 1000000)
            {
                return GetThousands(value, gender);
            }

            var millions = value / 1000000;
            var tensInMillions = millions % 100;
            var thousands = value % 1000000;

            var millionsText = GetPrefixText(millions, tensInMillions, "miljun", "żewġ miljuni", "miljuni", false, gender);
            var thousandsText = GetThousands(thousands, gender);

            if (thousands == 0)
            {
                return millionsText;
            }

            return $"{millionsText} u {thousandsText}";
        }

        private static string GetPrefixText(long thousands, long tensInThousands, string singular, string dual, string plural, bool usePrefixMapForLowerValueDigits, GrammaticalGender gender)
        {
            if (thousands == 1)
            {
                return singular;
            }

            if (thousands == 2)
            {
                return dual;
            }

            if (tensInThousands > 10)
            {
                return $"{GetHundreds(thousands, true, usePrefixMapForLowerValueDigits, gender)} {singular}";
            }

            if (thousands == 100)
            {
                return $"mitt {singular}";
            }

            if (thousands == 101)
            {
                return $"mija u {singular}";
            }

            return $"{GetHundreds(thousands, true, usePrefixMapForLowerValueDigits, gender)} {plural}";

        }
    }
}

using System;
using System.Collections.Generic;

namespace Humanizer.Localisation.NumberToWords
{
    internal class NorwegianBokmalNumberToWordsConverter : GenderedNumberToWordsConverter
    {
        private static readonly string[] UnitsMap = { "null", "en", "to", "tre", "fire", "fem", "seks", "sju", "åtte", "ni", "ti", "elleve", "tolv", "tretten", "fjorten", "femten", "seksten", "sytten", "atten", "nitten" };
        private static readonly string[] TensMap = { "null", "ti", "tjue", "tretti", "førti", "femti", "seksti", "sytti", "åtti", "nitti" };

        private static readonly Dictionary<int, string> OrdinalExceptions = new Dictionary<int, string>
        {
            {0, "nullte"},
            {1, "første"},
            {2, "andre"},
            {3, "tredje"},
            {4, "fjerde"},
            {5, "femte"},
            {6, "sjette"},
            {11, "ellevte"},
            {12, "tolvte"}
        };

        public override string Convert(long number, GrammaticalGender gender, bool addAnd = true)
        {
            if (number > Int32.MaxValue || number < Int32.MinValue)
            {
                throw new NotImplementedException();
            }

            return Convert((int)number, false, gender);
        }

        public override string ConvertToOrdinal(int number, GrammaticalGender gender)
        {
            return Convert(number, true, gender);
        }

        private string Convert(int number, bool isOrdinal, GrammaticalGender gender)
        {
            if (number == 0)
            {
                return GetUnitValue(0, isOrdinal);
            }

            if (number < 0)
            {
                return string.Format("minus {0}", Convert(-number, isOrdinal, gender));
            }

            if (number == 1)
            {
                switch (gender)
                {
                    case GrammaticalGender.Feminine:
                        return "ei";
                    case GrammaticalGender.Neuter:
                        return "et";
                }
            }

            var parts = new List<string>();

            var millionOrMore = false;

            const int billion = 1000000000;
            if ((number / billion) > 0)
            {
                millionOrMore = true;
                var isExactOrdinal = isOrdinal && number % billion == 0;
                parts.Add(Part("{0} milliard" + (isExactOrdinal ? "" : "er"), (isExactOrdinal ? "" : "en ") + "milliard", number / billion, !isExactOrdinal));
                number %= billion;
            }

            const int million = 1000000;
            if ((number / million) > 0)
            {
                millionOrMore = true;
                var isExactOrdinal = isOrdinal && number % million == 0;
                parts.Add(Part("{0} million" + (isExactOrdinal ? "" : "er"), (isExactOrdinal ? "" : "en ") + "million", number / million, !isExactOrdinal));
                number %= million;
            }

            var thousand = false;
            if ((number / 1000) > 0)
            {
                thousand = true;
                parts.Add(Part("{0}tusen", number % 1000 < 100 ? "tusen" : "ettusen", number / 1000));
                number %= 1000;
            }

            var hundred = false;
            if ((number / 100) > 0)
            {
                hundred = true;
                parts.Add(Part("{0}hundre", thousand || millionOrMore ? "ethundre" : "hundre", number / 100));
                number %= 100;
            }

            if (number > 0)
            {
                if (parts.Count != 0)
                {
                    if (millionOrMore && !hundred && !thousand)
                    {
                        parts.Add("og ");
                    }
                    else
                    {
                        parts.Add("og");
                    }
                }

                if (number < 20)
                {
                    parts.Add(GetUnitValue(number, isOrdinal));
                }
                else
                {
                    var lastPart = TensMap[number / 10];
                    if ((number % 10) > 0)
                    {
                        lastPart += string.Format("{0}", GetUnitValue(number % 10, isOrdinal));
                    }
                    else if (isOrdinal)
                    {
                        lastPart = lastPart.TrimEnd('e') + "ende";
                    }

                    parts.Add(lastPart);
                }
            }
            else if (isOrdinal)
            {
                parts[parts.Count - 1] += (number == 0 ? "" : "en") + (millionOrMore ? "te" : "de");
            }

            var toWords = string.Join("", parts.ToArray()).Trim();

            return toWords;
        }

        private static string GetUnitValue(int number, bool isOrdinal)
        {
            if (isOrdinal)
            {
                if (ExceptionNumbersToWords(number, out var exceptionString))
                {
                    return exceptionString;
                }
                else if (number < 13)
                {
                    return UnitsMap[number].TrimEnd('e') + "ende";
                }
                else
                {
                    return UnitsMap[number] + "de";
                }
            }
            else
            {
                return UnitsMap[number];
            }
        }

        private static bool ExceptionNumbersToWords(int number, out string words)
        {
            return OrdinalExceptions.TryGetValue(number, out words);
        }

        private string Part(string pluralFormat, string singular, int number, bool postfixSpace = false)
        {
            var postfix = postfixSpace ? " " : "";
            if (number == 1)
            {
                return singular + postfix;
            }

            return string.Format(pluralFormat, Convert(number)) + postfix;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;

namespace Humanizer.Localisation.NumberToWords
{
    internal class PolishNumberToWordsConverter : GenderedNumberToWordsConverter
    {
        private static readonly string[] HundredsMap =
        {
            "zero", "sto", "dwieście", "trzysta", "czterysta", "pięćset", "sześćset", "siedemset", "osiemset", "dziewięćset"
        };

        private static readonly string[] TensMap =
        {
            "zero", "dziesięć", "dwadzieścia", "trzydzieści", "czterdzieści", "pięćdziesiąt", "sześćdziesiąt", 
            "siedemdziesiąt", "osiemdziesiąt", "dziewięćdziesiąt"
        };

        private static readonly string[] UnitsMap =
        {
            "zero", "jeden", "dwa", "trzy", "cztery", "pięć", "sześć", "siedem", "osiem", "dziewięć", "dziesięć", 
            "jedenaście", "dwanaście", "trzynaście", "czternaście", "piętnaście", "szesnaście", "siedemnaście", 
            "osiemnaście", "dziewiętnaście"
        };

        private static readonly string[][] PowersOfThousandMap =
        {
            new []{"tysiąc", "tysiące", "tysięcy"},
            new []{"milion", "miliony", "milionów"},
            new []{"miliard", "miliardy", "miliardów"},
            new []{"bilion", "biliony", "bilionów"},
            new []{"biliard", "biliardy", "biliardów"},
            new []{"trylion", "tryliony", "trylionów"}
        };

        private const long MaxPossibleDivisor = 1_000_000_000_000_000_000;

        private readonly CultureInfo _culture;

        public PolishNumberToWordsConverter(CultureInfo culture)
        {
            _culture = culture;
        }

        public override string Convert(long input, GrammaticalGender gender, bool addAnd = true)
        {
            if (input == 0)
            {
                return "zero";
            }

            var parts = new List<string>();
            CollectParts(parts, input, gender);

            return string.Join(" ", parts);
        }

        public override string ConvertToOrdinal(int number, GrammaticalGender gender)
        {
            return number.ToString(_culture);
        }

        private static void CollectParts(ICollection<string> parts, long input, GrammaticalGender gender)
        {
            var inputSign = 1;
            if (input < 0)
            {
                parts.Add("minus");
                inputSign = -1;
            }

            var number = input;
            var divisor = MaxPossibleDivisor;
            var power = PowersOfThousandMap.Length - 1;
            while (divisor > 0)
            {
                var multiplier = (int) Math.Abs(number / divisor);
                if (divisor > 1)
                {
                    if (multiplier > 1)
                    {
                        CollectPartsUnderThousand(parts, multiplier, GrammaticalGender.Masculine);
                    }

                    if (multiplier > 0)
                    {
                        parts.Add(GetPowerOfThousandNameForm(multiplier, power));
                    }
                }
                else if (multiplier > 0)
                {
                    if (multiplier == 1 && Math.Abs(input) != 1)
                    {
                        gender = GrammaticalGender.Masculine;
                    }
                    CollectPartsUnderThousand(parts, multiplier, gender);
                }

                number -= multiplier * divisor * inputSign;
                divisor /= 1000;
                power--;
            }
        }

        private static void CollectPartsUnderThousand(ICollection<string> parts, int number, GrammaticalGender gender)
        {
            var hundredsDigit = number / 100;
            var tensDigit = (number % 100) / 10;
            var unitsDigit = number % 10;

            if (hundredsDigit >= 1)
            {
                parts.Add(HundredsMap[hundredsDigit]);
            }

            if (tensDigit >= 2)
            {
                parts.Add(TensMap[tensDigit]);
            }

            if (tensDigit != 1 && unitsDigit == 2)
            {
                var genderedForm = gender == GrammaticalGender.Feminine ? "dwie" : "dwa";
                parts.Add(genderedForm);
            }
            else if (number == 1)
            {
                var genderedForm = gender switch
                {
                    GrammaticalGender.Masculine => "jeden",
                    GrammaticalGender.Feminine => "jedna",
                    GrammaticalGender.Neuter => "jedno",
                    _ => throw new ArgumentOutOfRangeException(nameof(gender))
                };
                parts.Add(genderedForm);
            }
            else
            {
                var unit = unitsDigit + 10 * (tensDigit == 1 ? 1 : 0);
                if (unit > 0)
                {
                    parts.Add(UnitsMap[unit]);
                }
            }
        }

        private static string GetPowerOfThousandNameForm(int multiplier, int power)
        {
            const int singularIndex = 0;
            const int pluralIndex = 1;
            const int genitiveIndex = 2;
            if (multiplier == 1)
            {
                return PowersOfThousandMap[power][singularIndex];
            }

            var multiplierUnitsDigit = multiplier % 10;
            var multiplierTensDigit = (multiplier % 100) / 10;
            if (multiplierTensDigit == 1 || multiplierUnitsDigit <= 1 || multiplierUnitsDigit >= 5)
            {
                return PowersOfThousandMap[power][genitiveIndex];
            }
            return PowersOfThousandMap[power][pluralIndex];
        }
    }
}

using System;
using System.Collections.Generic;

namespace Humanizer.Localisation.NumberToWords
{
    internal class PortugueseNumberToWordsConverter : GenderedNumberToWordsConverter
    {
        private static readonly string[] PortugueseUnitsMap = { "zero", "um", "dois", "três", "quatro", "cinco", "seis", "sete", "oito", "nove", "dez", "onze", "doze", "treze", "quatorze", "quinze", "dezesseis", "dezessete", "dezoito", "dezenove" };
        private static readonly string[] PortugueseTensMap = { "zero", "dez", "vinte", "trinta", "quarenta", "cinquenta", "sessenta", "setenta", "oitenta", "noventa" };
        private static readonly string[] PortugueseHundredsMap = { "zero", "cento", "duzentos", "trezentos", "quatrocentos", "quinhentos", "seiscentos", "setecentos", "oitocentos", "novecentos" };

        private static readonly string[] PortugueseOrdinalUnitsMap = { "zero", "primeiro", "segundo", "terceiro", "quarto", "quinto", "sexto", "sétimo", "oitavo", "nono" };
        private static readonly string[] PortugueseOrdinalTensMap = { "zero", "décimo", "vigésimo", "trigésimo", "quadragésimo", "quinquagésimo", "sexagésimo", "septuagésimo", "octogésimo", "nonagésimo" };
        private static readonly string[] PortugueseOrdinalHundredsMap = { "zero", "centésimo", "ducentésimo", "trecentésimo", "quadringentésimo", "quingentésimo", "sexcentésimo", "septingentésimo", "octingentésimo", "noningentésimo" };

        public override string Convert(long input, GrammaticalGender gender, bool addAnd = true)
        {
            if (input > 999999999999 || input < -999999999999)
            {
                throw new NotImplementedException();
            }

            var number = input;

            if (number == 0)
            {
                return "zero";
            }

            if (number < 0)
            {
                return string.Format("menos {0}", Convert(Math.Abs(number), gender));
            }

            var parts = new List<string>();

            if ((number / 1000000000) > 0)
            {
                // gender is not applied for billions
                parts.Add(number / 1000000000 == 1
                    ? "mil milhões"
                    : string.Format("{0} mil milhões", Convert(number / 1000000000)));

                number %= 1000000000;
            }

            if ((number / 1000000) > 0)
            {
                // gender is not applied for millions
                parts.Add(number / 1000000 >= 2
                    ? string.Format("{0} milhões", Convert(number / 1000000, GrammaticalGender.Masculine))
                    : string.Format("{0} milhão", Convert(number / 1000000, GrammaticalGender.Masculine)));

                number %= 1000000;
            }

            if ((number / 1000) > 0)
            {
                // gender is not applied for thousands
                parts.Add(number / 1000 == 1 ? "mil" : string.Format("{0} mil", Convert(number / 1000, GrammaticalGender.Masculine)));
                number %= 1000;
            }

            if ((number / 100) > 0)
            {
                if (number == 100)
                {
                    parts.Add(parts.Count > 0 ? "e cem" : "cem");
                }
                else
                {
                    // Gender is applied to hundreds starting from 200
                    parts.Add(ApplyGender(PortugueseHundredsMap[(number / 100)], gender));
                }

                number %= 100;
            }

            if (number > 0)
            {
                if (parts.Count != 0)
                {
                    parts.Add("e");
                }

                if (number < 20)
                {
                    parts.Add(ApplyGender(PortugueseUnitsMap[number], gender));
                }
                else
                {
                    var lastPart = PortugueseTensMap[number / 10];
                    if ((number % 10) > 0)
                    {
                        lastPart += string.Format(" e {0}", ApplyGender(PortugueseUnitsMap[number % 10], gender));
                    }

                    parts.Add(lastPart);
                }
            }

            return string.Join(" ", parts.ToArray());
        }

        public override string ConvertToOrdinal(int number, GrammaticalGender gender)
        {
            // N/A in Portuguese ordinal
            if (number == 0)
            {
                return "zero";
            }

            var parts = new List<string>();

            if ((number / 1000000000) > 0)
            {
                parts.Add(number / 1000000000 == 1
                    ? string.Format("{0} {1}", ApplyOrdinalGender("milésimo", gender), ApplyOrdinalGender("milionésimo", gender))
                    : string.Format("{0} {1} {2}", Convert(number / 1000000000), ApplyOrdinalGender("milésimo", gender), ApplyOrdinalGender("milionésimo", gender)));

                number %= 1000000000;
            }

            if ((number / 1000000) > 0)
            {
                parts.Add(number / 1000000 == 1
                    ? ApplyOrdinalGender("milionésimo", gender)
                    : string.Format("{0} " + ApplyOrdinalGender("milionésimo", gender), ConvertToOrdinal(number / 1000000000, gender)));

                number %= 1000000;
            }

            if ((number / 1000) > 0)
            {
                parts.Add(number / 1000 == 1
                    ? ApplyOrdinalGender("milésimo", gender)
                    : string.Format("{0} " + ApplyOrdinalGender("milésimo", gender), ConvertToOrdinal(number / 1000, gender)));

                number %= 1000;
            }

            if ((number / 100) > 0)
            {
                parts.Add(ApplyOrdinalGender(PortugueseOrdinalHundredsMap[number / 100], gender));
                number %= 100;
            }

            if ((number / 10) > 0)
            {
                parts.Add(ApplyOrdinalGender(PortugueseOrdinalTensMap[number / 10], gender));
                number %= 10;
            }

            if (number > 0)
            {
                parts.Add(ApplyOrdinalGender(PortugueseOrdinalUnitsMap[number], gender));
            }

            return string.Join(" ", parts.ToArray());
        }

        private static string ApplyGender(string toWords, GrammaticalGender gender)
        {
            if (gender != GrammaticalGender.Feminine)
            {
                return toWords;
            }

            if (toWords.EndsWith("os"))
            {
                return toWords.Substring(0, toWords.Length - 2) + "as";
            }

            if (toWords.EndsWith("um"))
            {
                return toWords.Substring(0, toWords.Length - 2) + "uma";
            }

            if (toWords.EndsWith("dois"))
            {
                return toWords.Substring(0, toWords.Length - 4) + "duas";
            }

            return toWords;
        }

        private static string ApplyOrdinalGender(string toWords, GrammaticalGender gender)
        {
            if (gender == GrammaticalGender.Feminine)
            {
                return toWords.TrimEnd('o') + 'a';
            }

            return toWords;
        }
    }
}

using System;
using System.Collections.Generic;

namespace Humanizer.Localisation.NumberToWords.Romanian
{
    internal class RomanianCardinalNumberConverter
    {

        /// <summary>
        /// Lookup table converting units number to text. Index 1 for 1, index 2 for 2, up to index 9 for 9.
        /// </summary>
        private readonly string[] _units =
            {
                string.Empty,
                "unu|una|unu",
                "doi|două|două",
                "trei",
                "patru",
                "cinci",
                "șase",
                "șapte",
                "opt",
                "nouă"
            };

        /// <summary>
        /// Lookup table converting teens number to text. Index 0 for 10, index 1 for 11, up to index 9 for 19.
        /// </summary>
        private readonly string[] _teensUnder20NumberToText =
            {
                "zece",
                "unsprezece",
                "doisprezece|douăsprezece|douăsprezece",
                "treisprezece",
                "paisprezece",
                "cincisprezece",
                "șaisprezece",
                "șaptesprezece",
                "optsprezece",
                "nouăsprezece"
            };

        /// <summary>
        /// Lookup table converting tens number to text. Index 2 for 20, index 3 for 30, up to index 9 for 90.
        /// </summary>
        private readonly string[] _tensOver20NumberToText =
            {
                string.Empty,
                string.Empty,
                "douăzeci",
                "treizeci",
                "patruzeci",
                "cincizeci",
                "șaizeci",
                "șaptezeci",
                "optzeci",
                "nouăzeci"
            };

        private readonly string _feminineSingular = "o";
        private readonly string _masculineSingular = "un";

        private readonly string _joinGroups = "și";
        private readonly string _joinAbove20 = "de";
        private readonly string _minusSign = "minus";

        /// <summary>
        /// Enumerates sets of three-digits having distinct conversion to text.
        /// </summary>
        private enum ThreeDigitSets
        {
            /// <summary>
            /// Lowest three-digits set, from 1 to 999.
            /// </summary>
            Units = 0,

            /// <summary>
            /// Three-digits set counting the thousands, from 1'000 to 999'000.
            /// </summary>
            Thousands = 1,

            /// <summary>
            /// Three-digits set counting millions, from 1'000'000 to 999'000'000.
            /// </summary>
            Millions = 2,

            /// <summary>
            /// Three-digits set counting billions, from 1'000'000'000 to 999'000'000'000.
            /// </summary>
            Billions = 3,

            /// <summary>
            /// Three-digits set beyond 999 billions, from 1'000'000'000'000 onward.
            /// </summary>
            More = 4
        }

        public string Convert(int number, GrammaticalGender gender)
        {
            if (number == 0)
            {
                return "zero";
            }

            var words = string.Empty;

            var prefixMinusSign = false;

            if (number < 0)
            {
                prefixMinusSign = true;
                number = -number;
            }

            var _threeDigitParts = SplitEveryThreeDigits(number);

            for (var i = 0; i < _threeDigitParts.Count; i++)
            {

                var currentSet = (ThreeDigitSets)Enum.ToObject(typeof(ThreeDigitSets), i);

                var partToString = GetNextPartConverter(currentSet);

                words = partToString(_threeDigitParts[i], gender).Trim() + " " + words.Trim();
            }

            if (prefixMinusSign)
            {
                words = _minusSign + " " + words;
            }

            // remove extra spaces
            return words.TrimEnd().Replace("  ", " ");
        }

        /// <summary>
        /// Splits a number into a sequence of three-digits numbers,
        /// starting from units, then thousands, millions, and so on.
        /// </summary>
        /// <param name="number">The number to split.</param>
        /// <returns>The sequence of three-digit numbers.</returns>
        private List<int> SplitEveryThreeDigits(int number)
        {
            var parts = new List<int>();
            var rest = number;

            while (rest > 0)
            {
                var threeDigit = rest % 1000;

                parts.Add(threeDigit);

                rest = rest / 1000;
            }

            return parts;
        }

        /// <summary>
        /// During number conversion to text, finds out the converter
        /// to use for the next three-digit set.
        /// </summary>
        /// <returns>The next conversion function to use.</returns>
        private Func<int, GrammaticalGender, string> GetNextPartConverter(ThreeDigitSets currentSet)
        {
            Func<int, GrammaticalGender, string> converter;

            switch (currentSet)
            {
                case ThreeDigitSets.Units:
                    converter = UnitsConverter;
                    break;

                case ThreeDigitSets.Thousands:
                    converter = ThousandsConverter;
                    break;

                case ThreeDigitSets.Millions:
                    converter = MillionsConverter;
                    break;

                case ThreeDigitSets.Billions:
                    converter = BillionsConverter;
                    break;

                case ThreeDigitSets.More:
                    converter = null;
                    break;

                default:
                    throw new ArgumentOutOfRangeException("Unknow ThreeDigitSet: " + currentSet);
            }

            return converter;
        }

        /// <summary>
        /// Converts a three-digit set to text.
        /// </summary>
        /// <param name="number">The three-digit set to convert.</param>
        /// <param name="gender">The grammatical gender to convert to.</param>
        /// <param name="thisIsLastSet">True if the current three-digit set is the last in the word.</param>
        /// <returns>The same three-digit set expressed as text.</returns>
        private string ThreeDigitSetConverter(int number, GrammaticalGender gender, bool thisIsLastSet = false)
        {
            if (number == 0)
            {
                return string.Empty;
            }

            // grab lowest two digits
            var tensAndUnits = number % 100;
            // grab third digit
            var hundreds = number / 100;

            // grab also first and second digits separately
            var units = tensAndUnits % 10;
            var tens = tensAndUnits / 10;

            var words = string.Empty;

            // append text for hundreds
            words += HundredsToText(hundreds);

            // append text for tens, only those from twenty upward
            words += ((tens >= 2) ? " " : string.Empty) + _tensOver20NumberToText[tens];

            if (tensAndUnits <= 9)
            {
                // simple case for units, under 10
                words += " " + getPartByGender(_units[tensAndUnits], gender);
            }
            else if (tensAndUnits <= 19)
            {
                // special case for 'teens', from 10 to 19
                words += " " + getPartByGender(_teensUnder20NumberToText[tensAndUnits - 10], gender);
            }
            else
            {
                // exception for zero
                var unitsText = (units == 0 ? string.Empty : " " + (_joinGroups + " " + getPartByGender(_units[units], gender)));

                words += unitsText;
            }

            return words;
        }

        private string getPartByGender(string multiGenderPart, GrammaticalGender gender)
        {
            if (multiGenderPart.Contains("|"))
            {
                var parts = multiGenderPart.Split('|');
                if (gender == GrammaticalGender.Feminine)
                {
                    return parts[1];
                }

                if (gender == GrammaticalGender.Neuter)
                {
                    return parts[2];
                }
                else
                {
                    return parts[0];
                }
            }
            else
            {
                return multiGenderPart;
            }
        }

        private bool IsAbove20(int number)
        {
            return (number >= 20);
        }

        private string HundredsToText(int hundreds)
        {
            if (hundreds == 0)
            {
                return string.Empty;
            }
            else if (hundreds == 1)
            {
                return _feminineSingular + " sută";
            }
            else
            {
                return getPartByGender(_units[hundreds], GrammaticalGender.Feminine) + " sute";
            }
        }

        /// <summary>
        /// Converts a three-digit number, as units, to text.
        /// </summary>
        /// <param name="number">The three-digit number, as units, to convert.</param>
        /// <param name="gender">The grammatical gender to convert to.</param>
        /// <returns>The same three-digit number, as units, expressed as text.</returns>
        private string UnitsConverter(int number, GrammaticalGender gender)
        {
            return ThreeDigitSetConverter(number, gender, true);
        }


        /// <summary>
        /// Converts a thousands three-digit number to text.
        /// </summary>
        /// <param name="number">The three-digit number, as thousands, to convert.</param>
        /// <param name="gender">The grammatical gender to convert to.</param>
        /// <returns>The same three-digit number of thousands expressed as text.</returns>
        private string ThousandsConverter(int number, GrammaticalGender gender)
        {
            if (number == 0)
            {
                return string.Empty;
            }
            else if (number == 1)
            {
                return _feminineSingular + " mie";
            }
            else
            {
                return ThreeDigitSetConverter(number, GrammaticalGender.Feminine) + (IsAbove20(number) ? " " + _joinAbove20 : string.Empty) + " mii";
            }
        }

        // Large numbers (above 10^6) use a combined form of the long and short scales.
        /*
                Singular    Plural            Order     Scale
                -----------------------------------------------
                zece        zeci              10^1      -
                sută        sute              10^2      -
                mie         mii               10^3      -
                milion      milioane          10^6      short/long
                miliard     miliarde          10^9      long
                trilion     trilioane         10^12     short
        */

        /// <summary>
        /// Converts a millions three-digit number to text.
        /// </summary>
        /// <param name="number">The three-digit number, as millions, to convert.</param>
        /// <param name="gender">The grammatical gender to convert to.</param>
        /// <returns>The same three-digit number of millions expressed as text.</returns>
        private string MillionsConverter(int number, GrammaticalGender gender)
        {
            if (number == 0)
            {
                return string.Empty;
            }
            else if (number == 1)
            {
                return _masculineSingular + " milion";
            }
            else
            {
                return ThreeDigitSetConverter(number, GrammaticalGender.Feminine, true) + (IsAbove20(number) ? " " + _joinAbove20 : string.Empty) + " milioane";
            }
        }

        /// <summary>
        /// Converts a billions three-digit number to text.
        /// </summary>
        /// <param name="number">The three-digit number, as billions, to convert.</param>
        /// <param name="gender">The grammatical gender to convert to.</param>
        /// <returns>The same three-digit number of billions expressed as text.</returns>
        private string BillionsConverter(int number, GrammaticalGender gender)
        {
            if (number == 1)
            {
                return _masculineSingular + " miliard";
            }
            else
            {
                return ThreeDigitSetConverter(number, GrammaticalGender.Feminine) + (IsAbove20(number) ? " " + _joinAbove20 : string.Empty) + " miliarde";
            }
        }
    }
}

using System.Collections.Generic;

namespace Humanizer.Localisation.NumberToWords.Romanian
{
    internal class RomanianOrdinalNumberConverter
    {
        /// <summary>
        /// Lookup table converting units number to text. Index 1 for 1, index 2 for 2, up to index 9.
        /// </summary>
        private readonly Dictionary<int, string> _ordinalsUnder10 = new Dictionary<int, string>
            {
                {1, "primul|prima"},
                {2, "doilea|doua"},
                {3, "treilea|treia"},
                {4, "patrulea|patra"},
                {5, "cincilea|cincea"},
                {6, "șaselea|șasea"},
                {7, "șaptelea|șaptea"},
                {8, "optulea|opta"},
                {9, "nouălea|noua"},
            };

        private readonly string _femininePrefix = "a";
        private readonly string _masculinePrefix = "al";
        private readonly string _feminineSuffix = "a";
        private readonly string _masculineSuffix = "lea";

        public string Convert(int number, GrammaticalGender gender)
        {
            // it's easier to treat zero as a completely distinct case
            if (number == 0)
            {
                return "zero";
            }
            else if (number == 1)
            {
                // no prefixes for primul/prima
                return this.getPartByGender(_ordinalsUnder10[number], gender);
            }
            else if (number <= 9)
            {
                // units ordinals, 2 to 9, are totally different than the rest: treat them as a distinct case
                return string.Format("{0} {1}",
                                        gender == GrammaticalGender.Feminine ? _femininePrefix : _masculinePrefix,
                                        this.getPartByGender(_ordinalsUnder10[number], gender)
                                     );
            }
            else
            {
                var coverter = new RomanianCardinalNumberConverter();
                var words = coverter.Convert(number, gender);

                // remove 'de' preposition
                words = words.Replace(" de ", " ");

                if ((gender == GrammaticalGender.Feminine) && words.EndsWith("zeci"))
                {
                    words = words.Substring(0, words.Length - 4) + "zece";
                }
                else if ((gender == GrammaticalGender.Feminine) && words.Contains("zeci") && (words.Contains("milioane") || words.Contains("miliarde")))
                {
                    words = words.Replace("zeci", "zecea");
                }

                if ((gender == GrammaticalGender.Feminine) && words.StartsWith("un "))
                {
                    words = words.Substring(2).TrimStart();
                }

                if (words.EndsWith("milioane"))
                {
                    if (gender == GrammaticalGender.Feminine)
                    {
                        words = words.Substring(0, words.Length - 8) + "milioana";
                    }
                }

                var customMasculineSuffix = _masculineSuffix;
                if (words.EndsWith("milion"))
                {
                    if (gender == GrammaticalGender.Feminine)
                    {
                        words = words.Substring(0, words.Length - 6) + "milioana";
                    }
                    else
                    {
                        customMasculineSuffix = "u" + _masculineSuffix;
                    }
                }
                else if (words.EndsWith("miliard"))
                {
                    if (gender == GrammaticalGender.Masculine)
                    {
                        customMasculineSuffix = "u" + _masculineSuffix;
                    }
                }

                // trim last letter
                if ((gender == GrammaticalGender.Feminine) && (!words.EndsWith("zece") &&
                                                               (words.EndsWith("a") ||
                                                               words.EndsWith("ă") ||
                                                               words.EndsWith("e") ||
                                                               words.EndsWith("i"))))
                {
                    words = words.Substring(0, words.Length - 1);
                }

                return string.Format("{0} {1}{2}",
                                        gender == GrammaticalGender.Feminine ? _femininePrefix : _masculinePrefix,
                                        words,
                                        gender == GrammaticalGender.Feminine ? _feminineSuffix : customMasculineSuffix
                                    );
            }
        }

        private string getPartByGender(string multiGenderPart, GrammaticalGender gender)
        {
            if (multiGenderPart.Contains("|"))
            {
                var parts = multiGenderPart.Split('|');
                if (gender == GrammaticalGender.Feminine)
                {
                    return parts[1];
                }
                else
                {
                    return parts[0];
                }
            }
            else
            {
                return multiGenderPart;
            }
        }
    }
}

